// Writes assets/roots.txt: the project file, the scenes, every generated file under art/, models/, textures/ and luts/, and fonts/ with the fonts' licences.
// node tools/gen-roots.mjs
import { readdirSync, writeFileSync, statSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const A = join(dirname(fileURLToPath(import.meta.url)), '..', 'assets');
const lines = ['# partypack: what cwpack packs. Everything is generated by tools/ in this game or listed in CREDITS.', 'project.cwproj'];
for (const f of readdirSync(join(A, 'scenes')).sort()) lines.push(`scenes/${f}`);
for (const d of ["art", "models", "luts", "fonts"]) {
  if (!existsSync(join(A, d))) continue;
  for (const f of readdirSync(join(A, d)).sort()) if (statSync(join(A, d, f)).isFile() && ((d === 'fonts' && /OFL/.test(f)) || (!f.endsWith('.txt') && !f.endsWith('.md')))) lines.push(`${d}/${f}`);
}
writeFileSync(join(A, 'roots.txt'), lines.join('\n') + '\n');
console.log(lines.length, 'roots');
